 function wrap(s,max,size,bold=false){const out=[];for(const para of String(s).split(/\n/)){let line='';for(const word of para.split(/\s+/)){if(!word)continue;let next=line?line+' '+word:word;if(width(next,size,bold)>max&&line){out.push(line);line=word}else line=next;while(width(line,size,bold)>max&&line.length>1){let cut=line.length-1;while(cut>1&&width(line.slice(0,cut),size,bold)>max)cut--;out.push(line.slice(0,cut));line=line.slice(cut)}}out.push(line)}return out}
 let pages=[],ops=[],y=0;
