 function begin(){ops=[];y=top;text('New York State Companion Animal Care Standards Act Checklist',L,y,11,true);y+=15;text('Checklist export  |  '+new Date().toLocaleString(),L,y,7);y+=15;fill(L,y,W-L-R,19,'0.92');text('Requirement',L+5,y+12,8,true);['Yes','No','N/A'].forEach((v,j)=>text(v,W-R-3*col+j*col+5,y+12,7,true));y+=19;line(L,y,W-R,y)}
