 // Write a complete PDF file, with real page objects and downloadable bytes.
 const objects=[null];const add=s=>{objects.push(s);return objects.length-1};
 const catalog=add(''),root=add(''),font1=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'),font2=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');
 const kids=[];
 pages.forEach((content,i)=>{const footer='BT /F1 7 Tf 1 0 0 1 530 18 Tm ('+(i+1)+' / '+pages.length+') Tj ET';const stream=content+'\n'+footer;const streamId=add('<< /Length '+stream.length+' >>\nstream\n'+stream+'\nendstream');const pageId=add('<< /Type /Page /Parent '+root+' 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 '+font1+' 0 R /F2 '+font2+' 0 R >> >> /Contents '+streamId+' 0 R >>');kids.push(pageId)});
 objects[root]='<< /Type /Pages /Count '+kids.length+' /Kids ['+kids.map(id=>id+' 0 R').join(' ')+'] >>';objects[catalog]='<< /Type /Catalog /Pages '+root+' 0 R >>';
 let pdf='%PDF-1.4\n',offsets=[0];objects.slice(1).forEach((obj,i)=>{offsets.push(pdf.length);pdf+=(i+1)+' 0 obj\n'+obj+'\nendobj\n'});const xref=pdf.length;pdf+='xref\n0 '+objects.length+'\n0000000000 65535 f \n';offsets.slice(1).forEach(pos=>pdf+=String(pos).padStart(10,'0')+' 00000 n \n');pdf+='trailer\n<< /Size '+objects.length+' /Root '+catalog+' 0 R >>\nstartxref\n'+xref+'\n%%EOF';
